// AddTaskPage.js

import React, { useEffect, useState } from "react";
import { useParams, useNavigate } from "react-router-dom";

// ⭐ PRISMJS RENKLENDİRME
import Prism from "prismjs";
import "prismjs/themes/prism-okaidia.css";
import "prismjs/components/prism-clike";
import "prismjs/components/prism-javascript";
import "prismjs/components/prism-python";
import "prismjs/components/prism-markup";
import "prismjs/components/prism-json";
import "prismjs/components/prism-markdown";

/* ----------------------------------------------------
   PARTICLES
----------------------------------------------------- */
function FloatingParticles() {
    const [particles, setParticles] = useState([]);

    useEffect(() => {
        const generated = [...Array(55)].map(() => ({
            id: crypto.randomUUID(),
            left: Math.random() * 100,
            top: Math.random() * 100,
            delay: -(Math.random() * 15).toFixed(2),
            duration: 16 + Math.random() * 10,
        }));
        setParticles(generated);
    }, []);

    return (
        <div style={styles.particles}>
            {particles.map((p) => (
                <div
                    key={p.id}
                    style={{
                        ...styles.particle,
                        left: `${p.left}%`,
                        top: `${p.top}vh`,
                        animationDelay: `${p.delay}s`,
                        animationDuration: `${p.duration}s`,
                    }}
                />
            ))}
        </div>
    );
}

function AddTaskPage() {
    /* ===================== PREVIEW STATE ===================== */
    const [previewArtifact, setPreviewArtifact] = useState(null);
    const [previewURL, setPreviewURL] = useState("");
    const [previewText, setPreviewText] = useState("");
    const [previewLanguage, setPreviewLanguage] = useState("markup");
    const [previewLoading, setPreviewLoading] = useState(false);

    const { studyId } = useParams();
    const navigate = useNavigate();

    /* ===================== STUDY TYPE ===================== */
    const [studyType, setStudyType] = useState(null);

    const [artifacts, setArtifacts] = useState([]);
    const [questionText, setQuestionText] = useState("");
    const [description, setDescription] = useState("");
    const [artifactCount, setArtifactCount] = useState(2);
    const [selectedArtifacts, setSelectedArtifacts] = useState([]);
    const [loading, setLoading] = useState(true);

    /* ===================== CORRECT ANSWER STATE ===================== */
    const [correctAnswer, setCorrectAnswer] = useState({
        // BUG (multi)
        configurationIssue: false,
        networkIssue: false,
        databaseIssue: false,
        guiIssue: false,
        performanceIssue: false,
        permissionIssue: false,
        securityIssue: false,
        functionalIssue: false,
        testCodeIssue: false,

        // CODE CLONE (single)
        type1: false,
        type2: false,
        type3: false,
        type4: false,
        notClone: false,

        // SNAPSHOT_TESTING — UI change categories (multi, min 1)
        colorChange: false,
        shapeChange: false,
        positionChange: false,
        layoutChange: false,
        visibilityChange: false,
        fontChange: false,
        contentChange: false,
        sizeChange: false,
        unknownChange: false,

        // SOLID principles (multi, min 1)
        srp: false,
        ocp: false,
        lsp: false,
        isp: false,
        dip: false,

        // SOLID difficulty (single: easy/medium/hard)
        easy: false,
        medium: false,
        hard: false,
    });

    /* SEARCH + FILTER */
    const [search, setSearch] = useState("");
    const [filter, setFilter] = useState("all");

    const [toast, setToast] = useState(null);

    const showSuccess = (message) => {
        setToast({ type: "success", message });
        setTimeout(() => setToast(null), 2000);
    };

    const showError = (message) => {
        setToast({ type: "error", message });
        setTimeout(() => setToast(null), 2000);
    };

    /* ================= TAG LIMIT RULES ===================== */
    const tagRules = {
        CODE_CLONE: { requiredTags: ["original", "clone"], total: 2 },
        SNAPSHOT_TESTING: { requiredTags: ["reference", "failure", "diff"], total: 3 },
    };

    const validateTagRules = (studyType, selectedIds) => {
        const rule = tagRules[studyType];
        if (!rule) return true;
        if (selectedIds.length !== rule.total) return true;

        const tagsArray = selectedIds.map((id) => {
            const art = artifacts.find((a) => a.id === id);
            return (art?.tags || "").toLowerCase();
        });

        return rule.requiredTags.every((req) =>
            tagsArray.some((t) => t.includes(req))
        );
    };

    /* Tooltip logic */
    const [hoveredLockedField, setHoveredLockedField] = useState(null);
    const [tooltipPos, setTooltipPos] = useState({ x: 0, y: 0, direction: "right" });

    const handleMouseMove = (e) => {
        const direction = e.clientX > window.innerWidth * 0.6 ? "right" : "left";
        setTooltipPos({ x: e.clientX, y: e.clientY, direction });
    };

    const getStudyTypeLabel = (value) => {
        switch (value) {
            case "BUG_CATEGORIZATION":
                return "Bug Categorization";
            case "CODE_CLONE":
                return "Code Clone";
            case "SNAPSHOT_TESTING":
                return "Snapshot Testing";
            case "SOLID_DETECTION":
                return "SOLID Detection";
            case "CUSTOM":
                return "Custom";
            default:
                return value;
        }
    };

    /* Prism */
    useEffect(() => {
        if (previewText) Prism.highlightAll();
    }, [previewText]);

    /* ============================================================
       FETCH STUDY TYPE
    ============================================================ */
    useEffect(() => {
        const fetchStudy = async () => {
            try {
                const token = localStorage.getItem("token");
                const res = await fetch(
                    `http://localhost:8080/api/studies/${studyId}`,
                    {
                        headers: {
                            Authorization: `Bearer ${token}`,
                            "Content-Type": "application/json",
                        },
                    }
                );

                if (!res.ok) throw new Error("Failed to fetch study");

                const study = await res.json();
                setStudyType(study.studyType);
            } catch (err) {
                console.error("Study fetch error:", err);
                showError("❌ Error loading study details");
            }
        };

        fetchStudy();
    }, [studyId]);

    /* ============================================================
       AUTO-FILL FOR NON-CUSTOM STUDY TYPES
    ============================================================ */
    useEffect(() => {
        if (!studyType) return;

        if (studyType !== "CUSTOM") {
            if (studyType === "BUG_CATEGORIZATION") {
                setQuestionText("Categorize the given bug report.");
                setDescription(
                    "Select the correct issue type based on the JSON bug report."
                );
                setArtifactCount(1);
            }

            if (studyType === "CODE_CLONE") {
                setQuestionText(
                    "Identify the clone type between the two code blocks."
                );
                setDescription(
                    "Choose from Type-1, Type-2, Type-3 or Type-4 clone categories."
                );
                setArtifactCount(2);
            }

            if (studyType === "SNAPSHOT_TESTING") {
                setQuestionText(
                    "Identify the UI change(s) between the snapshots."
                );
                setDescription(
                    "Inspect reference, failure, and diff images, then select the applicable visual change categories."
                );
                setArtifactCount(3);
            }

            if (studyType === "SOLID_DETECTION") {
                setQuestionText("Identify the violated SOLID principle(s).");
                setDescription(
                    "Mark all violated SOLID principles and rate the difficulty of the given code block as Easy, Medium or Hard."
                );
                setArtifactCount(1);
            }

            setSelectedArtifacts([]);
        }
    }, [studyType]);

    /* ============================================================
       FETCH ARTIFACTS
    ============================================================ */
    useEffect(() => {
        const fetchArtifacts = async () => {
            try {
                const token = localStorage.getItem("token");
                const res = await fetch(
                    "http://localhost:8080/api/artifacts/my-artifacts",
                    { headers: { Authorization: `Bearer ${token}` } }
                );

                if (!res.ok) throw new Error("Failed loading artifacts");
                const data = await res.json();
                setArtifacts(data);
            } catch (err) {
                console.error("Artifact fetch error:", err);
                showError("❌ Error loading artifacts");
            } finally {
                setLoading(false);
            }
        };

        fetchArtifacts();
    }, []);

    /* ============================================================
       FILE HELPERS
    ============================================================ */
    const getFileIcon = (filename) => {
        const ext = filename.split(".").pop().toLowerCase();
        switch (ext) {
            case "java":
                return "☕";
            case "cpp":
                return "⚙️";
            case "py":
                return "🐍";
            case "js":
                return "📜";
            case "ts":
                return "🟦";
            case "pdf":
                return "📕";
            case "txt":
                return "📄";
            default:
                return "📄";
        }
    };

    const getFileColor = (filename) => {
        const ext = filename.split(".").pop().toLowerCase();
        switch (ext) {
            case "java":
                return {
                    bg: "rgba(244,114,182,0.18)",
                    color: "#f472b6",
                    border: "rgba(244,114,182,0.4)",
                };
            case "cpp":
                return {
                    bg: "rgba(96,165,250,0.18)",
                    color: "#60a5fa",
                    border: "rgba(96,165,250,0.4)",
                };
            case "py":
                return {
                    bg: "rgba(250,204,21,0.18)",
                    color: "#fde047",
                    border: "rgba(250,204,21,0.4)",
                };
            case "js":
                return {
                    bg: "rgba(34,197,94,0.18)",
                    color: "#4ade80",
                    border: "rgba(34,197,94,0.4)",
                };
            default:
                return {
                    bg: "rgba(156,163,175,0.18)",
                    color: "#9ca3af",
                    border: "rgba(156,163,175,0.4)",
                };
        }
    };

    /* ============================================================
       ARTIFACT SELECTION
    ============================================================ */
    const toggleArtifactSelection = (id) => {
        if (selectedArtifacts.includes(id)) {
            setSelectedArtifacts((prev) => prev.filter((x) => x !== id));
            return;
        }

        if (selectedArtifacts.length >= artifactCount) {
            return showError(`⚠️ You can only select ${artifactCount} artifacts`);
        }

        const newSel = [...selectedArtifacts, id];
        const rule = tagRules[studyType];

        if (!rule) return setSelectedArtifacts(newSel);

        if (newSel.length > rule.total) {
            return showError(
                `⚠️ You must select exactly ${rule.total} artifacts for ${studyType}`
            );
        }

        if (newSel.length < rule.total) {
            return setSelectedArtifacts(newSel);
        }

        if (!validateTagRules(studyType, newSel)) {
            return showError(
                `⚠️ Required tags: ${rule.requiredTags.join(", ")}`
            );
        }

        setSelectedArtifacts(newSel);
    };

    /* ============================================================
       PREVIEW HANDLER
    ============================================================ */
    const handlePreview = async (artifact) => {
        try {
            const token = localStorage.getItem("token");
            const url = `http://localhost:8080/researcher/artifact/${artifact.id}`;

            setPreviewArtifact(artifact);
            setPreviewLoading(true);
            setPreviewText("");
            setPreviewURL("");

            const response = await fetch(url, {
                headers: { Authorization: `Bearer ${token}` },
            });

            if (!response.ok) throw new Error("Preview failed");

            const blob = await response.blob();
            const blobURL = URL.createObjectURL(blob);
            const filename = artifact.filename.toLowerCase();

            if (filename.match(/\.(pdf|png|jpg|jpeg)$/i)) {
                setPreviewURL(blobURL);
            } else {
                const ext = filename.split(".").pop();
                const langMap = {
                    java: "clike",
                    js: "javascript",
                    ts: "javascript",
                    py: "python",
                    c: "clike",
                    cpp: "clike",
                    html: "markup",
                    css: "markup",
                    md: "markdown",
                    json: "json",
                    txt: "markup",
                };
                setPreviewLanguage(langMap[ext] || "markup");
                setPreviewText(await blob.text());
            }
        } catch (err) {
            console.error(err);
            setPreviewText("Preview not supported.");
        } finally {
            setPreviewLoading(false);
        }
    };

    /* ============================================================
       CORRECT ANSWER HELPERS (single vs multi choice)
    ============================================================ */
    const toggleMultiChoice = (key) => {
        setCorrectAnswer((prev) => ({
            ...prev,
            [key]: !prev[key],
        }));
    };

    const toggleSingleChoice = (groupKeys, key) => {
        setCorrectAnswer((prev) => {
            const isAlreadySelected = prev[key];
            const updated = { ...prev };
            groupKeys.forEach((k) => {
                updated[k] = false;
            });
            // Eğer aynı butona tekrar basılırsa hepsini sıfırla (hepsini kapat)
            if (!isAlreadySelected) {
                updated[key] = true;
            }
            return updated;
        });
    };

    const countSelected = (keys) =>
        keys.reduce((acc, k) => acc + (correctAnswer[k] ? 1 : 0), 0);

    /* ============================================================
       CREATE TASK (includes correct answers)
    ============================================================ */
    const handleCreateTask = async () => {
        if (!questionText.trim()) return showError("⚠️ Enter task question");
        if (!description.trim()) return showError("⚠️ Enter description");
        if (selectedArtifacts.length !== artifactCount)
            return showError(`⚠️ Select exactly ${artifactCount} artifacts`);

        if (!validateTagRules(studyType, selectedArtifacts)) {
            const rule = tagRules[studyType];
            if (rule) {
                return showError(
                    `⚠️ Required tags: ${rule.requiredTags.join(", ")}`
                );
            }
        }

        // ✅ STUDY TYPE'A GÖRE CORRECT ANSWER VALIDATION
        if (studyType === "CODE_CLONE") {
            const cloneKeys = ["type1", "type2", "type3", "type4", "notClone"];   // ⭐
            if (countSelected(cloneKeys) !== 1) {
                return showError("⚠️ Please select exactly ONE clone type as the correct answer.");
            }
        }


        if (studyType === "SNAPSHOT_TESTING") {
            const snapshotKeys = [
                "colorChange",
                "shapeChange",
                "positionChange",
                "layoutChange",
                "visibilityChange",
                "fontChange",
                "contentChange",
                "sizeChange",
                "unknownChange",
            ];
            if (countSelected(snapshotKeys) < 1) {
                return showError(
                    "⚠️ Please select AT LEAST ONE UI change category."
                );
            }
        }

        if (studyType === "BUG_CATEGORIZATION") {
            const bugCategoryKeys = [
                "configurationIssue",
                "networkIssue",
                "databaseIssue",
                "guiIssue",
                "performanceIssue",
                "permissionIssue",
                "securityIssue",
                "functionalIssue",
                "testCodeIssue",
            ];

            if (countSelected(bugCategoryKeys) < 1) {
                return showError("⚠️ Please select AT LEAST ONE bug category.");
            }
        }

        if (studyType === "SOLID_DETECTION") {
            const difficultyKeys = ["easy", "medium", "hard"];
            const principleKeys = ["srp", "ocp", "lsp", "isp", "dip"];

            // ✅ Difficulty: exactly ONE
            if (countSelected(difficultyKeys) !== 1) {
                return showError(
                    "⚠️ Please select exactly ONE difficulty level (Easy / Medium / Hard)."
                );
            }

            // ✅ SOLID Principles: multi + en az 1 zorunlu
            if (countSelected(principleKeys) < 1) {
                return showError(
                    "⚠️ Please select AT LEAST ONE violated SOLID principle."
                );
            }
        }

        const token = localStorage.getItem("token");

        // ⭐ Backend’e gönderilecek payload
        const payload = {
            questionText,
            description,
            artifactCount,
            artifactIds: selectedArtifacts,
            ...correctAnswer,
        };

        try {
            const res = await fetch(
                `http://localhost:8080/api/tasks/create/${studyId}`,
                {
                    method: "POST",
                    headers: {
                        "Content-Type": "application/json",
                        Authorization: `Bearer ${token}`,
                    },
                    body: JSON.stringify(payload),
                }
            );

            if (!res.ok) throw new Error();

            showSuccess("✅ Task created!");
            setTimeout(() => navigate(`/manage-tasks/${studyId}`), 1500);
        } catch (err) {
            console.error(err);
            showError("❌ Failed to create task");
        }
    };

    /* ============================================================
       ALLOWED EXTENSIONS PER STUDY TYPE
    ============================================================ */
    const allowedExtensionsByType = {
        BUG_CATEGORIZATION: ["json"],
        SOLID_DETECTION: ["json"],
        CODE_CLONE: [
            "java",
            "py",
            "cpp",
            "c",
            "h",
            "js",
            "ts",
            "txt",
            "md",
            "rb",
            "go",
            "rs",
        ],
        SNAPSHOT_TESTING: ["png", "jpg", "jpeg"],
        CUSTOM: null,
    };

    const allowedExts =
        studyType && allowedExtensionsByType[studyType]
            ? allowedExtensionsByType[studyType]
            : null;

    const getUniqueExtensions = () => {
        const extensions = new Set();
        artifacts.forEach((art) => {
            const ext = art.filename.split(".").pop().toLowerCase();
            extensions.add(ext);
        });
        return Array.from(extensions).sort();
    };

    const uniqueExtensions = getUniqueExtensions();

    const filteredArtifacts = artifacts.filter((art) => {
        const lower = art.filename.toLowerCase();
        const ext = lower.split(".").pop();

        if (allowedExts && !allowedExts.includes(ext)) return false;
        const matchesSearch = lower.includes(search.toLowerCase());
        const matchesFilter = filter === "all" || filter === ext;

        return matchesSearch && matchesFilter;
    });

    /* ============================================================
       CORRECT ANSWERS UI — studyType based
    ============================================================ */
    const renderCorrectAnswerFields = () => {
        if (!studyType || studyType === "CUSTOM") return null;

        const bugKeys = [
            { key: "configurationIssue", label: "CONFIGURATION ISSUE" },
            { key: "networkIssue", label: "NETWORK ISSUE" },
            { key: "databaseIssue", label: "DATABASE ISSUE" },
            { key: "guiIssue", label: "GUI ISSUE" },
            { key: "performanceIssue", label: "PERFORMANCE ISSUE" },
            { key: "permissionIssue", label: "PERMISSION ISSUE" },
            { key: "securityIssue", label: "SECURITY ISSUE" },
            { key: "functionalIssue", label: "FUNCTIONAL ISSUE" },
            { key: "testCodeIssue", label: "TEST CODE ISSUE" },
        ];

        const cloneKeys = [
            { key: "type1", label: "TYPE-1" },
            { key: "type2", label: "TYPE-2" },
            { key: "type3", label: "TYPE-3" },
            { key: "type4", label: "TYPE-4" },
            { key: "notClone", label: "NOT A CLONE" },
        ];

        const snapshotKeys = [
            { key: "colorChange", label: "COLOR CHANGE" },
            { key: "shapeChange", label: "SHAPE CHANGE" },
            { key: "positionChange", label: "POSITION CHANGE" },
            { key: "layoutChange", label: "LAYOUT CHANGE" },
            { key: "visibilityChange", label: "VISIBILITY CHANGE" },
            { key: "fontChange", label: "FONT CHANGE" },
            { key: "contentChange", label: "CONTENT CHANGE" },
            { key: "sizeChange", label: "SIZE CHANGE" },
            { key: "unknownChange", label: "OTHER / UNKNOWN" },
        ];

        const solidPrincipleKeys = [
            { key: "srp", label: "SRP" },
            { key: "ocp", label: "OCP" },
            { key: "lsp", label: "LSP" },
            { key: "isp", label: "ISP" },
            { key: "dip", label: "DIP" },
        ];

        const solidDifficultyKeys = [
            { key: "easy", label: "EASY" },
            { key: "medium", label: "MEDIUM" },
            { key: "hard", label: "HARD" },
        ];

        if (studyType === "BUG_CATEGORIZATION")
            return (
                <div style={styles.answerBox}>
                    <h3 style={styles.answerTitle}>Correct Bug Category</h3>
                    <p style={styles.answerHint}>
                        You can select <strong>one or more</strong> bug types as
                        correct.
                    </p>
                    <div style={styles.answerRow}>
                        {bugKeys.map(({ key, label }) => (
                            <label key={key} style={styles.answerCheck}>
                                <input
                                    type="checkbox"
                                    checked={correctAnswer[key]}
                                    onChange={() => toggleMultiChoice(key)}
                                    style={styles.answerCheckbox}
                                />
                                <span
                                    style={{
                                        ...styles.answerChip,
                                        ...(correctAnswer[key]
                                            ? styles.answerChipActive
                                            : {}),
                                    }}
                                >
                                    {label}
                                </span>
                            </label>
                        ))}
                    </div>
                </div>
            );

        if (studyType === "CODE_CLONE") {
            const groupKeys = cloneKeys.map((k) => k.key);
            return (
                <div style={styles.answerBox}>
                    <h3 style={styles.answerTitle}>Correct Clone Type</h3>
                    <p style={styles.answerHint}>
                        Exactly <strong>one</strong> clone type must be selected.
                    </p>
                    <div style={styles.answerRow}>
                        {cloneKeys.map(({ key, label }) => (
                            <label key={key} style={styles.answerCheck}>
                                <input
                                    type="checkbox"
                                    checked={correctAnswer[key]}
                                    onChange={() =>
                                        toggleSingleChoice(groupKeys, key)
                                    }
                                    style={styles.answerCheckbox}
                                />
                                <span
                                    style={{
                                        ...styles.answerChip,
                                        ...(correctAnswer[key]
                                            ? styles.answerChipActive
                                            : {}),
                                    }}
                                >
                                    {label}
                                </span>
                            </label>
                        ))}
                    </div>
                </div>
            );
        }

        if (studyType === "SNAPSHOT_TESTING") {
            return (
                <div style={styles.answerBox}>
                    <h3 style={styles.answerTitle}>UI Change Categories</h3>
                    <p style={styles.answerHint}>
                        Select <strong>one or more</strong> visual change categories
                        that describe the difference between the snapshots.
                    </p>
                    <div style={styles.answerRow}>
                        {snapshotKeys.map(({ key, label }) => (
                            <label key={key} style={styles.answerCheck}>
                                <input
                                    type="checkbox"
                                    checked={correctAnswer[key]}
                                    onChange={() => toggleMultiChoice(key)}
                                    style={styles.answerCheckbox}
                                />
                                <span
                                    style={{
                                        ...styles.answerChip,
                                        ...(correctAnswer[key]
                                            ? styles.answerChipActive
                                            : {}),
                                    }}
                                >
                                    {label}
                                </span>
                            </label>
                        ))}
                    </div>
                </div>
            );
        }

        if (studyType === "SOLID_DETECTION")
            return (
                <div style={{ display: "flex", gap: "40px", flexWrap: "wrap" }}>
                    <div style={{ ...styles.answerBox, flex: 1 }}>
                        <h3 style={styles.answerTitle}>Violated Principle</h3>
                        <p style={styles.answerHint}>
                            You can select <strong>one or more</strong> violated
                            principles. At least one is required.
                        </p>
                        <div style={styles.answerRow}>
                            {solidPrincipleKeys.map(({ key, label }) => (
                                <label key={key} style={styles.answerCheck}>
                                    <input
                                        type="checkbox"
                                        checked={correctAnswer[key]}
                                        onChange={() =>
                                            toggleMultiChoice(key)
                                        }
                                        style={styles.answerCheckbox}
                                    />
                                    <span
                                        style={{
                                            ...styles.answerChip,
                                            ...(correctAnswer[key]
                                                ? styles.answerChipActive
                                                : {}),
                                        }}
                                    >
                                        {label}
                                    </span>
                                </label>
                            ))}
                        </div>
                    </div>

                    <div style={{ ...styles.answerBox, flex: 1 }}>
                        <h3 style={styles.answerTitle}>Difficulty</h3>
                        <p style={styles.answerHint}>
                            Select exactly <strong>one</strong> difficulty level.
                        </p>
                        <div style={styles.answerRow}>
                            {solidDifficultyKeys.map(({ key, label }) => {
                                const groupKeys = solidDifficultyKeys.map(
                                    (k) => k.key
                                );
                                return (
                                    <label key={key} style={styles.answerCheck}>
                                        <input
                                            type="checkbox"
                                            checked={correctAnswer[key]}
                                            onChange={() =>
                                                toggleSingleChoice(
                                                    groupKeys,
                                                    key
                                                )
                                            }
                                            style={styles.answerCheckbox}
                                        />
                                        <span
                                            style={{
                                                ...styles.answerChip,
                                                ...(correctAnswer[key]
                                                    ? styles.answerChipActive
                                                    : {}),
                                            }}
                                        >
                                            {label}
                                        </span>
                                    </label>
                                );
                            })}
                        </div>
                    </div>
                </div>
            );

        return null;
    };

    /* ============================================================
       TOOLTIP TEXT
    ============================================================ */
    const isPreset = studyType && studyType !== "CUSTOM";
    const prettyType = getStudyTypeLabel(studyType);

    const getTooltipText = () => {
        if (!isPreset || !hoveredLockedField) return "";
        if (hoveredLockedField === "question") {
            return `This field is auto-generated by Study Type: ${prettyType}. You cannot edit it.`;
        }
        if (hoveredLockedField === "description") {
            return `This field is auto-generated by Study Type: ${prettyType}. You cannot edit it.`;
        }
        if (hoveredLockedField === "artifactCount") {
            return `Artifact count is fixed for ${prettyType} studies.`;
        }
        return "";
    };

    /* ============================================================
       RENDER
    ============================================================ */
    if (loading) {
        return (
            <p style={{ padding: 40, color: "white" }}>Loading artifacts...</p>
        );
    }

    return (
        <div style={styles.container} onMouseMove={handleMouseMove}>
            <FloatingParticles />

            {/* TOAST (üst orta) */}
            {toast && (
                <div
                    style={{
                        ...styles.toast,
                        ...(toast.type === "success"
                            ? styles.toastSuccess
                            : styles.toastError),
                    }}
                >
                    {toast.message}
                </div>
            )}

            {/* NAVBAR */}
            <div style={styles.navbar}>
                <h2 style={styles.navTitle}>➕ Create New Task</h2>

                <div style={{ display: "flex", gap: "12px" }}>
                    <button
                        style={styles.uploadButton}
                        onClick={() => navigate("/upload-artifact")}
                    >
                        ⬆️ Upload New Artifact
                    </button>

                    <button
                        className="back-btn"
                        style={styles.backButton}
                        onClick={() => navigate(`/manage-tasks/${studyId}`)}
                    >
                        ← Back
                    </button>
                </div>
            </div>

            <div style={styles.content}>
                {/* QUESTION */}
                <div style={styles.field}>
                    <label style={styles.label}>Task Question</label>
                    <div style={{ position: "relative" }}>
                        {isPreset && (
                            <div
                                onMouseEnter={() =>
                                    setHoveredLockedField("question")
                                }
                                onMouseLeave={() =>
                                    setHoveredLockedField(null)
                                }
                                style={{
                                    position: "absolute",
                                    inset: 0,
                                    cursor: "not-allowed",
                                    zIndex: 5,
                                    background: "transparent",
                                }}
                            />
                        )}
                        <input
                            type="text"
                            placeholder="Enter the evaluation question..."
                            value={questionText}
                            onChange={(e) =>
                                setQuestionText(e.target.value)
                            }
                            disabled={isPreset}
                            style={{
                                ...styles.input,
                                opacity: isPreset ? 0.6 : 1,
                            }}
                        />
                    </div>
                </div>

                {/* DESCRIPTION */}
                <div style={styles.field}>
                    <label style={styles.label}>Task Description</label>
                    <div style={{ position: "relative" }}>
                        {isPreset && (
                            <div
                                onMouseEnter={() =>
                                    setHoveredLockedField("description")
                                }
                                onMouseLeave={() =>
                                    setHoveredLockedField(null)
                                }
                                style={{
                                    position: "absolute",
                                    inset: 0,
                                    cursor: "not-allowed",
                                    zIndex: 5,
                                    background: "transparent",
                                }}
                            />
                        )}
                        <textarea
                            placeholder="Describe what the participant should evaluate..."
                            value={description}
                            onChange={(e) =>
                                setDescription(e.target.value)
                            }
                            disabled={isPreset}
                            style={{
                                ...styles.textarea,
                                opacity: isPreset ? 0.6 : 1,
                            }}
                        />
                    </div>
                </div>

                {/* ARTIFACT COUNT */}
                <div style={styles.field}>
                    <label style={styles.label}>Number of Artifacts</label>
                    <div style={{ position: "relative" }}>
                        {isPreset && (
                            <div
                                onMouseEnter={() =>
                                    setHoveredLockedField("artifactCount")
                                }
                                onMouseLeave={() =>
                                    setHoveredLockedField(null)
                                }
                                style={{
                                    position: "absolute",
                                    inset: 0,
                                    cursor: "not-allowed",
                                    zIndex: 5,
                                    background: "transparent",
                                }}
                            />
                        )}
                        <select
                            value={artifactCount}
                            onChange={(e) => {
                                setArtifactCount(Number(e.target.value));
                                setSelectedArtifacts([]);
                            }}
                            disabled={isPreset}
                            style={{
                                ...styles.select,
                                opacity: isPreset ? 0.6 : 1,
                            }}
                        >
                            {[1, 2, 3, 4, 5].map((n) => (
                                <option key={n} value={n}>
                                    {n} Artifacts
                                </option>
                            ))}
                        </select>
                    </div>
                </div>

                {/* ARTIFACTS SECTION */}
                <div style={styles.section}>
                    <div style={styles.sectionHeader}>
                        <h2 style={styles.sectionTitle}>📂 Select Artifacts</h2>
                        <span style={styles.selectionCounter}>
                            {selectedArtifacts.length} / {artifactCount} selected
                        </span>
                    </div>

                    {/* SEARCH + FILTER */}
                    <div style={styles.searchRow}>
                        <input
                            type="text"
                            placeholder="🔍 Search artifacts..."
                            value={search}
                            onChange={(e) => setSearch(e.target.value)}
                            style={styles.searchInput}
                        />
                        <select
                            value={filter}
                            onChange={(e) => setFilter(e.target.value)}
                            style={styles.filterSelect}
                        >
                            <option value="all">
                                All Types (
                                {allowedExts
                                    ? artifacts.filter((a) =>
                                        allowedExts.includes(
                                            a.filename
                                                .split(".")
                                                .pop()
                                                .toLowerCase()
                                        )
                                    ).length
                                    : artifacts.length}
                                )
                            </option>

                            {(allowedExts
                                    ? uniqueExtensions.filter((ext) =>
                                        allowedExts.includes(ext)
                                    )
                                    : uniqueExtensions
                            ).map((ext) => {
                                const count = artifacts.filter(
                                    (art) =>
                                        art.filename
                                            .split(".")
                                            .pop()
                                            .toLowerCase() === ext
                                ).length;

                                return (
                                    <option key={ext} value={ext}>
                                        {ext.toUpperCase()} ({count})
                                    </option>
                                );
                            })}
                        </select>
                    </div>

                    {/* GRID */}
                    <div style={styles.artifactGrid}>
                        {filteredArtifacts.map((art) => {
                            const isSelected =
                                selectedArtifacts.includes(art.id);
                            const colors = getFileColor(art.filename);

                            return (
                                <div
                                    key={art.id}
                                    onClick={() =>
                                        toggleArtifactSelection(art.id)
                                    }
                                    style={{
                                        ...styles.artifactCard,
                                        background: isSelected
                                            ? "rgba(96,165,250,0.35)"
                                            : "rgba(255,255,255,0.05)",
                                        border: `2px solid ${
                                            isSelected
                                                ? "rgba(96,165,250,0.8)"
                                                : "rgba(255,255,255,0.1)"
                                        }`,
                                        transform: isSelected
                                            ? "scale(1.03)"
                                            : "scale(1)",
                                        boxShadow: isSelected
                                            ? "0 0 15px rgba(96,165,250,0.8)"
                                            : "none",
                                    }}
                                >
                                    {/* EYE BUTTON */}
                                    <div
                                        className="eye-hover"
                                        style={styles.eyeButton}
                                        onClick={(e) => {
                                            e.stopPropagation();
                                            handlePreview(art);
                                        }}
                                    >
                                        <svg
                                            width="20"
                                            height="20"
                                            viewBox="0 0 24 24"
                                            fill="none"
                                            stroke="#60a5fa"
                                            strokeWidth="2"
                                            strokeLinecap="round"
                                            strokeLinejoin="round"
                                        >
                                            <path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"></path>
                                            <circle
                                                cx="12"
                                                cy="12"
                                                r="3"
                                            ></circle>
                                        </svg>
                                    </div>

                                    <div style={styles.artifactIcon}>
                                        {getFileIcon(art.filename)}
                                    </div>

                                    <div style={styles.artifactInfo}>
                                        <h4 style={styles.artifactFilename}>
                                            {art.filename}
                                        </h4>

                                        <div style={styles.artifactMeta}>
                                            <span
                                                style={{
                                                    ...styles.artifactType,
                                                    color: colors.color,
                                                    background: colors.bg,
                                                    border: `1px solid ${colors.border}`,
                                                }}
                                            >
                                                {art.category || "File"}
                                            </span>

                                            <span style={styles.tagBadge}>
                                                {art.tags ? art.tags : "No Tags"}
                                            </span>
                                        </div>
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                </div>

                {/* CORRECT ANSWER SECTION (non-CUSTOM study types) */}
                {studyType && studyType !== "CUSTOM" && (
                    <div style={styles.section}>
                        <h2 style={styles.sectionTitle}>
                            ✅ Correct Answer (Researcher Only)
                        </h2>
                        <p
                            style={{
                                fontSize: "0.9rem",
                                color: "rgba(209,213,219,0.9)",
                                marginBottom: "12px",
                            }}
                        >
                            These fields define the expected correct answer for
                            this task. Participant responses will be compared
                            against this configuration in the reviewer screens.
                        </p>

                        {renderCorrectAnswerFields()}
                    </div>
                )}

                <button style={styles.createBtn} onClick={handleCreateTask}>
                    ✔ Create Task
                </button>
            </div>

            {/* MODAL */}
            {previewArtifact && (
                <div
                    style={styles.modalOverlay}
                    onClick={() => setPreviewArtifact(null)}
                >
                    <div
                        style={styles.modalContent}
                        onClick={(e) => e.stopPropagation()}
                    >
                        <h2 style={styles.previewTitle}>
                            {previewArtifact.filename}
                        </h2>

                        {previewLoading ? (
                            <p style={{ color: "#93c5fd" }}>
                                Loading preview...
                            </p>
                        ) : (
                            <>
                                {previewURL &&
                                    previewArtifact.filename.endsWith(
                                        ".pdf"
                                    ) && (
                                        <embed
                                            src={previewURL}
                                            type="application/pdf"
                                            style={styles.previewPDF}
                                        />
                                    )}

                                {previewURL &&
                                    previewArtifact.filename.match(
                                        /\.(png|jpg|jpeg)$/i
                                    ) && (
                                        <img
                                            src={previewURL}
                                            alt="preview"
                                            style={styles.previewImage}
                                        />
                                    )}

                                {previewText && (
                                    <pre style={styles.previewPre}>
                                        <code
                                            className={`language-${previewLanguage}`}
                                        >
                                            {previewText}
                                        </code>
                                    </pre>
                                )}
                            </>
                        )}

                        <button
                            className="close-btn"
                            style={styles.closeButton}
                            onClick={() => setPreviewArtifact(null)}
                        >
                            Close
                        </button>
                    </div>
                </div>
            )}

            {/* FLOATING TOOLTIP */}
            {hoveredLockedField && isPreset && (
                <div
                    style={{
                        ...styles.tooltip,
                        top: tooltipPos.y + 12,
                        left:
                            tooltipPos.direction === "right"
                                ? tooltipPos.x + 24
                                : tooltipPos.x - 260,
                    }}
                >
                    {getTooltipText()}

                    {/* ARROW */}
                    <div
                        style={{
                            position: "absolute",
                            top: "14px",
                            [tooltipPos.direction === "right"
                                ? "left"
                                : "right"]: "-9px",
                            width: 0,
                            height: 0,
                            borderTop: "8px solid transparent",
                            borderBottom: "8px solid transparent",
                            borderLeft:
                                tooltipPos.direction === "right"
                                    ? "8px solid rgba(255, 165, 0, 0.7)"
                                    : "none",
                            borderRight:
                                tooltipPos.direction === "left"
                                    ? "8px solid rgba(255, 165, 0, 0.7)"
                                    : "none",
                        }}
                    />
                </div>
            )}

            {/* KEYFRAMES */}
            <style>
                {`
                    @keyframes floatParticle {
                        0% { transform: translateY(0); opacity: .4; }
                        50% { opacity: 1; }
                        100% { transform: translateY(-120vh); opacity: 0; }
                    }

                    @keyframes toastFade {
                        0% { opacity: 0; transform: translateX(-50%) translateY(-6px); }
                        100% { opacity: 1; transform: translateX(-50%) translateY(0); }
                    }

                    @keyframes fadeTooltip {
                        0% { opacity: 0; transform: translateY(-4px); }
                        100% { opacity: 1; transform: translateY(0); }
                    }
                `}
            </style>
        </div>
    );
}

